using System.Net;
using System.Net.Http.Json;
using FluentAssertions;
using Mindzyxs_API.Tests.Integration;
using Xunit;

namespace Mindzyxs_API.Tests.Integration;

public class PruebasControladorAccountExtra : IClassFixture<FabricaAplicacionWebApiConDatos>
{
    private readonly HttpClient _client;
    public PruebasControladorAccountExtra(FabricaAplicacionWebApiConDatos factory) { factory.SeedDatabase(); _client = factory.CreateClient(); }

    [Fact] public async Task ObtenerPerfil_SinToken_ReturnsUnauthorized() { var r = await _client.GetAsync("/api/account/perfil"); r.StatusCode.Should().Be(HttpStatusCode.Unauthorized); }
    [Fact] public async Task ActualizarPerfil_SinToken_ReturnsUnauthorized() { var r = await _client.PutAsJsonAsync("/api/account/perfil", new { nombres = "A", apellidos = "B" }); r.StatusCode.Should().Be(HttpStatusCode.Unauthorized); }
    [Fact] public async Task SolicitarCambioCorreo_SinToken_ReturnsUnauthorized() { var r = await _client.PostAsJsonAsync("/api/account/correo/solicitar", new { nuevoCorreo = "x@test.com" }); r.StatusCode.Should().Be(HttpStatusCode.Unauthorized); }
    [Fact] public async Task ConfirmarCambioCorreo_SinToken_ReturnsUnauthorized() { var r = await _client.PostAsJsonAsync("/api/account/correo/confirmar", new { nuevoCorreo = "x@test.com", codigo = "123456" }); r.StatusCode.Should().Be(HttpStatusCode.Unauthorized); }
    [Fact] public async Task VerifyCode_Invalido_ReturnsBadRequest() { var r = await _client.PostAsJsonAsync("/api/account/forgot/verify", new { correo = "paciente@test.com", codigo = "000000" }); r.StatusCode.Should().BeOneOf(HttpStatusCode.BadRequest, HttpStatusCode.Gone); }
    [Fact] public async Task ResetPassword_Invalido_ReturnsBadRequest() { var r = await _client.PostAsJsonAsync("/api/account/forgot/reset", new { correo = "paciente@test.com", codigo = "000000", password = "Abc12345" }); r.StatusCode.Should().BeOneOf(HttpStatusCode.BadRequest, HttpStatusCode.Gone); }
    [Fact] public async Task Register_TipoInvalido_ReturnsBadRequest() { var content = new MultipartFormDataContent(); content.Add(new StringContent("Medico"), "TipoUsuario"); var r = await _client.PostAsync("/api/account/register", content); r.StatusCode.Should().Be(HttpStatusCode.BadRequest); }
    [Fact] public async Task Register_NombreVacio_ReturnsBadRequest() { var content = new MultipartFormDataContent(); content.Add(new StringContent("Paciente"), "TipoUsuario"); content.Add(new StringContent(""), "Nombre"); content.Add(new StringContent("User"), "Apellido"); content.Add(new StringContent("x@test.com"), "Correo"); content.Add(new StringContent("Abc12345"), "Password"); content.Add(new StringContent("2000-01-01"), "FechaNacimiento"); content.Add(new StringContent("1"), "IdGenero"); var r = await _client.PostAsync("/api/account/register", content); r.StatusCode.Should().Be(HttpStatusCode.BadRequest); }
    [Fact] public async Task Register_CorreoInvalido_ReturnsBadRequest() { var content = new MultipartFormDataContent(); content.Add(new StringContent("Paciente"), "TipoUsuario"); content.Add(new StringContent("Test"), "Nombre"); content.Add(new StringContent("User"), "Apellido"); content.Add(new StringContent("invalid"), "Correo"); content.Add(new StringContent("Abc12345"), "Password"); content.Add(new StringContent("2000-01-01"), "FechaNacimiento"); content.Add(new StringContent("1"), "IdGenero"); var r = await _client.PostAsync("/api/account/register", content); r.StatusCode.Should().Be(HttpStatusCode.BadRequest); }
    [Fact] public async Task Register_PasswordDebil_ReturnsBadRequest() { var content = new MultipartFormDataContent(); content.Add(new StringContent("Paciente"), "TipoUsuario"); content.Add(new StringContent("Test"), "Nombre"); content.Add(new StringContent("User"), "Apellido"); content.Add(new StringContent("weak@test.com"), "Correo"); content.Add(new StringContent("abc"), "Password"); content.Add(new StringContent("2000-01-01"), "FechaNacimiento"); content.Add(new StringContent("1"), "IdGenero"); var r = await _client.PostAsync("/api/account/register", content); r.StatusCode.Should().Be(HttpStatusCode.BadRequest); }
    [Fact] public async Task Register_FechaFutura_ReturnsBadRequest() { var content = new MultipartFormDataContent(); content.Add(new StringContent("Paciente"), "TipoUsuario"); content.Add(new StringContent("Test"), "Nombre"); content.Add(new StringContent("User"), "Apellido"); content.Add(new StringContent("futuro@test.com"), "Correo"); content.Add(new StringContent("Abc12345"), "Password"); content.Add(new StringContent(DateTime.UtcNow.AddDays(1).ToString("yyyy-MM-dd")), "FechaNacimiento"); content.Add(new StringContent("1"), "IdGenero"); var r = await _client.PostAsync("/api/account/register", content); r.StatusCode.Should().Be(HttpStatusCode.BadRequest); }
    [Fact] public async Task Register_GeneroInvalido_ReturnsBadRequest() { var content = new MultipartFormDataContent(); content.Add(new StringContent("Paciente"), "TipoUsuario"); content.Add(new StringContent("Test"), "Nombre"); content.Add(new StringContent("User"), "Apellido"); content.Add(new StringContent("gen@test.com"), "Correo"); content.Add(new StringContent("Abc12345"), "Password"); content.Add(new StringContent("2000-01-01"), "FechaNacimiento"); content.Add(new StringContent("999"), "IdGenero"); var r = await _client.PostAsync("/api/account/register", content); r.StatusCode.Should().Be(HttpStatusCode.BadRequest); }
    [Fact] public async Task Verify_CorreoInvalido_ReturnsBadRequest() { var r = await _client.PostAsJsonAsync("/api/account/verify", new { correo = "invalid", codigo = "123456" }); r.StatusCode.Should().Be(HttpStatusCode.BadRequest); }
    [Fact] public async Task Verify_CodigoVacio_ReturnsBadRequest() { var r = await _client.PostAsJsonAsync("/api/account/verify", new { correo = "paciente@test.com", codigo = "" }); r.StatusCode.Should().Be(HttpStatusCode.BadRequest); }
    [Fact] public async Task Forgot_CorreoVacio_ReturnsBadRequest() { var r = await _client.PostAsJsonAsync("/api/account/forgot", new { correo = "" }); r.StatusCode.Should().Be(HttpStatusCode.BadRequest); }
    [Fact] public async Task ForgotResend_CorreoVacio_ReturnsBadRequest() { var r = await _client.PostAsJsonAsync("/api/account/forgot/resend", new { correo = "" }); r.StatusCode.Should().Be(HttpStatusCode.BadRequest); }
    [Fact] public async Task Login_PasswordVacio_ReturnsBadRequest() { var r = await _client.PostAsJsonAsync("/api/account/login", new { correo = "paciente@test.com", password = "" }); r.StatusCode.Should().Be(HttpStatusCode.BadRequest); }
}
